129	/// Best-effort recovery of a stale/disconnected Linux FUSE mount before
130	/// (re)mounting at the same path.
131	///
132	/// A crashed FUSE session leaves the mount point in a disconnected state where
133	/// `stat()` returns ENOTCONN, so `Path::exists()` lies (returns false). We
134	/// instead consult `/proc/self/mountinfo` authoritatively; if the mount point
135	/// is still present we unmount it (`fusermount3 -u`, then lazy `fusermount3 -z
136	/// -u` as a fallback for the disconnected case).
137	///
138	/// This is best-effort: any error (failure to read mountinfo, failed unmount)
139	/// is logged and the function returns so the caller proceeds with its normal
140	/// `exists()` / `create_dir_all` / clean-stale logic.
141	pub fn recover_stale_mount(mount_path: &Path) {
142	    let mountinfo = match std::fs::read_to_string("/proc/self/mountinfo") {
143	        Ok(contents) => contents,
144	        Err(e) => {
145	            log::info!(
146	                "recover_stale_mount: could not read /proc/self/mountinfo ({}); skipping",
147	                e
148	            );
149	            return;
150	        }
151	    };
152	
153	    if !mountinfo_contains_mountpoint(&mountinfo, mount_path) {
154	        // Not currently mounted (or not stale); nothing to recover.
155	        return;
156	    }
157	
158	    log::info!(
159	        "recover_stale_mount: stale mount detected at {}; unmounting",
160	        mount_path.display()
161	    );
162	
163	    // Try a normal unmount first.
164	    if try_fusermount3_unmount(mount_path, &["-u"]) {
165	        log::info!(
166	            "recover_stale_mount: unmounted stale mount via fusermount3 -u at {}",
167	            mount_path.display()
168	        );
169	        return;
170	    }
171	    log::info!("recover_stale_mount: fusermount3 -u failed; trying lazy fusermount3 -z -u");
172	
173	    // Lazy unmount fallback for the disconnected case. -z detaches the mount
174	    // now and cleans up references as they are released; acceptable since we
175	    // immediately mount a fresh session at the same path.
176	    if try_fusermount3_unmount(mount_path, &["-z", "-u"]) {
177	        log::info!(
178	            "recover_stale_mount: lazily unmounted stale mount via fusermount3 -z -u at {}",
179	            mount_path.display()
180	        );
181	    } else {
182	        log::info!(
183	            "recover_stale_mount: lazy fusermount3 -z -u also failed at {}; proceeding anyway",
184	            mount_path.display()
185	        );
186	    }
187	}
188	
189	/// Run `fusermount3 <args> <mount_path>` and report whether it exited
190	/// successfully. Spawn/exec failures count as not-successful.
191	fn try_fusermount3_unmount(mount_path: &Path, args: &[&str]) -> bool {
192	    matches!(
193	        std::process::Command::new("fusermount3")
194	            .args(args)
195	            .arg(mount_path)
196	            .status(),
197	        Ok(s) if s.success()
198	    )
199	}
200	
201	/// Pure decision helper: should a `create_dir_all` error trigger
202	/// recover-then-retry-once?
203	///
204	/// Returns true only for `ErrorKind::AlreadyExists` (EEXIST), which is the
205	/// symptom of a disconnected FUSE mount whose dirent still exists. Any other
206	/// error kind propagates to the caller unchanged.
207	pub(crate) fn should_recover_then_retry(err_kind: std::io::ErrorKind) -> bool {
208	    err_kind == std::io::ErrorKind::AlreadyExists
209	}
210	
211	/// Create the mount-point directory, recovering once from a stale FUSE mount.
212	///
213	/// Belt-and-suspenders for the Linux stale-mount case: a disconnected FUSE
214	/// mount whose dirent still exists surfaces as EEXIST from `create_dir_all`
215	/// even though `Path::exists()` returned false. On that specific error we
216	/// recover the stale mount and retry once; any other error propagates.
217	pub fn create_mount_point_dir(mount_path: &Path) -> std::io::Result<()> {
218	    match std::fs::create_dir_all(mount_path) {
219	        Ok(()) => Ok(()),
220	        Err(e) if should_recover_then_retry(e.kind()) => {
221	            recover_stale_mount(mount_path);
222	            std::fs::create_dir_all(mount_path)
223	        }
224	        Err(e) => Err(e),
225	    }
226	}
